csharp\nusing Fusion;\nusing UnityEngine;\n\nnamespace AirHockey.Core.Physics\n{\n [RequireComponent(typeof(Rigidbody2D), typeof(Collider2D))]\n public class PuckController : NetworkBehaviour\n {\n [SerializeField] private float maxSpeed = 20f;\n [SerializeField] private float linearDrag = 0.25f;\n private Rigidbody2D rb;\n\n public override void Spawned()\n {\n rb = GetComponent<Rigidbody2D>();\n rb.drag = linearDrag;\n }\n\n private void FixedUpdate()\n {\n if (rb.velocity.magnitude > maxSpeed)\n rb.velocity = rb.velocity.normalized * maxSpeed;\n }\n\n private void OnTriggerEnter2D(Collider2D col)\n {\n if (!Object.HasStateAuthority) return;\n\n if (col.CompareTag(\"GoalLeft\")) GameManager.Instance.GoalScored(false);\n else if (col.CompareTag(\"GoalRight\")) GameManager.Instance.GoalScored(true);\n }\n }\n}\n